parts:
Below is a practical, minimal implementation that still covers your requirements:

- **Backend (Node.js/Express + PostgreSQL)**  
  - Deduct stock when a purchase happens
  - **Concurrency-safe** (prevents negative stock under simultaneous buys)
  - Logs when stock becomes **< 5**
  - Keeps **history/audit log** of stock changes
- **Frontend (React)**  
  - Dashboard showing all stock
  - Separate list of low-stock items

---

## Backend (Node.js) — Controller + routes + DB schema

### 1) PostgreSQL schema (tables)
```sql
-- products table
CREATE TABLE IF NOT EXISTS products (
  id           BIGSERIAL PRIMARY KEY,
  sku          TEXT UNIQUE NOT NULL,
  name         TEXT NOT NULL,
  stock        INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- stock history/audit table
CREATE TABLE IF NOT EXISTS stock_history (
  id            BIGSERIAL PRIMARY KEY,
  product_id    BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  change_type   TEXT NOT NULL CHECK (change_type IN ('PURCHASE','ADJUSTMENT','RESTOCK')),
  delta         INTEGER NOT NULL, -- negative for deduction, positive for restock
  before_stock  INTEGER NOT NULL,
  after_stock   INTEGER NOT NULL,
  reason        TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_products_stock ON products(stock);
CREATE INDEX IF NOT EXISTS idx_stock_history_product_id ON stock_history(product_id);
```

### 2) DB client (`db.js`)
```js
// db.js
const { Pool } = require("pg");

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // ssl: { rejectUnauthorized: false }, // enable if needed on your host
});

module.exports = { pool };
```

### 3) Inventory controller (`inventoryController.js`)
```js
// inventoryController.js
const { pool } = require("./db");

/**
 * POST /api/inventory/purchase
 * body: { productId: number, quantity: number, orderId?: string }
 */
async function purchaseItem(req, res) {
  const { productId, quantity, orderId } = req.body;

  if (!Number.isInteger(productId) || productId <= 0) {
    return res.status(400).json({ error: "productId must be a positive integer" });
  }
  if (!Number.isInteger(quantity) || quantity <= 0) {
    return res.status(400).json({ error: "quantity must be a positive integer" });
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    // Lock the row so concurrent purchases can’t oversell
    const productRes = await client.query(
      `SELECT id, name, stock
       FROM products
       WHERE id = $1
       FOR UPDATE`,
      [productId]
    );

    if (productRes.rowCount === 0) {
      await client.query("ROLLBACK");
      return res.status(404).json({ error: "Product not found" });
    }

    const product = productRes.rows[0];
    const beforeStock = product.stock;

    if (beforeStock < quantity) {
      await client.query("ROLLBACK");
      return res.status(409).json({
        error: "Insufficient stock",
        available: beforeStock,
        requested: quantity,
      });
    }

    const afterStock = beforeStock - quantity;

    await client.query(
      `UPDATE products
       SET stock = $1, updated_at = NOW()
       WHERE id = $2`,
      [afterStock, productId]
    );

    // History record (delta is negative for purchase)
    await client.query(
      `INSERT INTO stock_history
         (product_id, change_type, delta, before_stock, after_stock, reason)
       VALUES
         ($1, 'PURCHASE', $2, $3, $4, $5)`,
      [
        productId,
        -quantity,
        beforeStock,
        afterStock,
        orderId ? `orderId=${orderId}` : "purchase",
      ]
    );

    await client.query("COMMIT");

    // Low stock logging requirement
    if (afterStock < 5) {
      console.log(`[LOW STOCK] productId=${productId} name="${product.name}" stock=${afterStock}`);
    }

    return res.json({
      ok: true,
      productId,
      beforeStock,
      afterStock,
      purchased: quantity,
    });
  } catch (err) {
    await client.query("ROLLBACK");
    console.error("purchaseItem error:", err);
    return res.status(500).json({ error: "Internal server error" });
  } finally {
    client.release();
  }
}

/**
 * GET /api/inventory/stock
 * Returns all products with current stock
 */
async function getStock(req, res) {
  try {
    const result = await pool.query(
      `SELECT id, sku, name, stock, updated_at
       FROM products
       ORDER BY name ASC`
    );
    res.json({ items: result.rows });
  } catch (err) {
    console.error("getStock error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
}

/**
 * GET /api/inventory/low-stock?threshold=5
 * Returns products where stock < threshold (default 5)
 */
async function getLowStock(req, res) {
  const thresholdRaw = req.query.threshold;
  const threshold = thresholdRaw ? Number(thresholdRaw) : 5;

  if (!Number.isFinite(threshold) || threshold < 0) {
    return res.status(400).json({ error: "threshold must be a non-negative number" });
  }

  try {
    const result = await pool.query(
      `SELECT id, sku, name, stock, updated_at
       FROM products
       WHERE stock < $1
       ORDER BY stock ASC, name ASC`,
      [threshold]
    );
    res.json({ threshold, items: result.rows });
  } catch (err) {
    console.error("getLowStock error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
}

/**
 * GET /api/inventory/history/:productId
 * Stock change history for a product
 */
async function getStockHistory(req, res) {
  const productId = Number(req.params.productId);
  if (!Number.isInteger(productId) || productId <= 0) {
    return res.status(400).json({ error: "productId must be a positive integer" });
  }

  try {
    const result = await pool.query(
      `SELECT id, change_type, delta, before_stock, after_stock, reason, created_at
       FROM stock_history
       WHERE product_id = $1
       ORDER BY created_at DESC
       LIMIT 200`,
      [productId]
    );
    res.json({ productId, history: result.rows });
  } catch (err) {
    console.error("getStockHistory error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
}

module.exports = {
  purchaseItem,
  getStock,
  getLowStock,
  getStockHistory,
};
```

### 4) Routes + app wiring (`routes.js`, `server.js`)
```js
// routes.js
const express = require("express");
const {
  purchaseItem,
  getStock,
  getLowStock,
  getStockHistory,
} = require("./inventoryController");

const router = express.Router();

router.get("/inventory/stock", getStock);
router.get("/inventory/low-stock", getLowStock);
router.get("/inventory/history/:productId", getStockHistory);
router.post("/inventory/purchase", purchaseItem);

module.exports = router;
```

```js
// server.js
require("dotenv").config();
const express = require("express");
const cors = require("cors");
const routes = require("./routes");

const app = express();

app.use(cors());
app.use(express.json());
app.use("/api", routes);

const port = process.env.PORT || 3001;
app.listen(port, () => {
  console.log(`Inventory API running on port ${port}`);
});
```

**Test purchase**
```bash
curl -X POST http://localhost:3001/api/inventory/purchase \
  -H "Content-Type: application/json" \
  -d '{"productId":1,"quantity":2,"orderId":"ORD-1001"}'
```

