## Frontend (React) — Dashboard component

This component fetches:
- `/api/inventory/stock` (all items)
- `/api/inventory/low-stock?threshold=5` (low-stock list)

```jsx
import React, { useEffect, useMemo, useState } from "react";

const API_BASE = import.meta?.env?.VITE_API_BASE ?? "http://localhost:3001/api";

function formatDate(iso) {
  if (!iso) return "-";
  const d = new Date(iso);
  return isNaN(d.getTime()) ? "-" : d.toLocaleString();
}

export default function InventoryDashboard() {
  const [items, setItems] = useState([]);
  const [lowStockItems, setLowStockItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [search, setSearch] = useState("");

  async function load() {
    setLoading(true);
    setErr("");

    try {
      const [stockRes, lowRes] = await Promise.all([
        fetch(`${API_BASE}/inventory/stock`),
        fetch(`${API_BASE}/inventory/low-stock?threshold=5`),
      ]);

      if (!stockRes.ok) throw new Error(`Stock request failed (${stockRes.status})`);
      if (!lowRes.ok) throw new Error(`Low-stock request failed (${lowRes.status})`);

      const stockJson = await stockRes.json();
      const lowJson = await lowRes.json();

      setItems(stockJson.items ?? []);
      setLowStockItems(lowJson.items ?? []);
    } catch (e) {
      setErr(e?.message || "Failed to load inventory");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return items;
    return items.filter((p) => {
      const sku = (p.sku || "").toLowerCase();
      const name = (p.name || "").toLowerCase();
      return sku.includes(q) || name.includes(q);
    });
  }, [items, search]);

  return (
    <div style={{ padding: 24, fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, Arial" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
        <h2 style={{ margin: 0 }}>Inventory Dashboard</h2>
        <button onClick={load} disabled={loading} style={{ padding: "8px 12px", cursor: "pointer" }}>
          {loading ? "Loading..." : "Refresh"}
        </button>
      </div>

      {err ? (
        <div style={{ marginTop: 12, padding: 12, background: "#ffecec", border: "1px solid #ffb3b3" }}>
          <strong>Error:</strong> {err}
        </div>
      ) : null}

      <div style={{ marginTop: 16, display: "flex", gap: 12, alignItems: "center" }}>
        <input
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search by SKU or name..."
          style={{ flex: 1, padding: 10, borderRadius: 8, border: "1px solid #ccc" }}
        />
      </div>

      <div style={{ marginTop: 18, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
        {/* Current Stock */}
        <section style={{ padding: 16, border: "1px solid #e5e5e5", borderRadius: 12 }}>
          <h3 style={{ marginTop: 0 }}>Current Stock</h3>
          <div style={{ fontSize: 13, color: "#555", marginBottom: 10 }}>
            Total products: <strong>{filtered.length}</strong>
          </div>

          <div style={{ overflow: "auto", maxHeight: 420 }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  <th style={{ textAlign: "left", padding: 8, borderBottom: "1px solid #eee" }}>SKU</th>
                  <th style={{ textAlign: "left", padding: 8, borderBottom: "1px solid #eee" }}>Name</th>
                  <th style={{ textAlign: "right", padding: 8, borderBottom: "1px solid #eee" }}>Stock</th>
                  <th style={{ textAlign: "left", padding: 8, borderBottom: "1px solid #eee" }}>Updated</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((p) => (
                  <tr key={p.id}>
                    <td style={{ padding: 8, borderBottom: "1px solid #f3f3f3" }}>{p.sku}</td>
                    <td style={{ padding: 8, borderBottom: "1px solid #f3f3f3" }}>{p.name}</td>
                    <td style={{ padding: 8, borderBottom: "1px solid #f3f3f3", textAlign: "right" }}>
                      <strong style={{ color: p.stock < 5 ? "#b00020" : "inherit" }}>{p.stock}</strong>
                    </td>
                    <td style={{ padding: 8, borderBottom: "1px solid #f3f3f3", color: "#666", fontSize: 12 }}>
                      {formatDate(p.updated_at)}
                    </td>
                  </tr>
                ))}
                {!loading && filtered.length === 0 ? (
                  <tr>
                    <td colSpan={4} style={{ padding: 10, color: "#777" }}>
                      No products found.
                    </td>
                  </tr>
                ) : null}
              </tbody>
            </table>
          </div>
        </section>

        {/* Low Stock */}
        <section style={{ padding: 16, border: "1px solid #e5e5e5", borderRadius: 12 }}>
          <h3 style={{ marginTop: 0 }}>Low-stock Items (stock &lt; 5)</h3>
          <div style={{ fontSize: 13, color: "#555", marginBottom: 10 }}>
            Count: <strong>{lowStockItems.length}</strong>
          </div>

          <div style={{ display: "grid", gap: 10 }}>
            {lowStockItems.map((p) => (
              <div
                key={p.id}
                style={{
                  padding: 12,
                  borderRadius: 10,
                  border: "1px solid #f0d0d0",
                  background: "#fff7f7",
                  display: "flex",
                  justifyContent: "space-between",
                  gap: 12,
                }}
              >
                <div>
                  <div style={{ fontWeight: 700 }}>{p.name}</div>
                  <div style={{ color: "#666", fontSize: 12 }}>SKU: {p.sku}</div>
                  <div style={{ color: "#666", fontSize: 12 }}>Updated: {formatDate(p.updated_at)}</div>
                </div>
                <div style={{ fontWeight: 800, color: "#b00020", fontSize: 18 }}>{p.stock}</div>
              </div>
            ))}

            {!loading && lowStockItems.length === 0 ? (
              <div style={{ padding: 12, color: "#555", background: "#f7fff7", border: "1px solid #d7f5d7", borderRadius: 10 }}>
                No low-stock items 🎉
              </div>
            ) : null}
          </div>
        </section>
      </div>
    </div>
  );
}
```

**If you’re using Create React App instead of Vite:** replace `import.meta.env...` with `process.env.REACT_APP_API_BASE`.

---

If you want, I can also add:
- an **“Adjust stock”** endpoint (manual restock/adjustment with history)
- a **single endpoint** that returns both stock + low-stock in one call
- pagination + sorting + basic auth for admin dashboard

Absolutely — here’s a complete “small but real” online shop + inventory system you can run locally without needing to write code.

What you’ll get:

- **Backend (Node.js/Express + PostgreSQL)**
  - Products list
  - Buy product (subtract stock safely)
  - Admin restock/add stock (increase stock)
  - Low-stock list (stock < 5) + logs
  - Stock change history (audit trail)
- **Frontend (React)**
  - **Shop page** (customers can buy)
  - **Dashboard page** (see inventory + low stock + restock button)
- **Database setup** (SQL included)
- **Run instructions** in a **README**
- **Docker Compose** so you can start everything with a few commands

---

